;p2test.asm — generated by p2gen.py:, the Pentium II's transcript image: every
; MMX instruction over eight operand pairs (register and memory forms, the
; shifts by register and by immediate, counts past the lane), MOVD both
; ways; then by hand: the tag word and TOP after MMX and after EMMS, what
; the x87 sees in a register MMX wrote, #UD (CR0.EM), #NM (CR0.TS) and #MF
; (a pending x87 exception) on an MMX instruction, SYSENTER and SYSEXIT
; (the segments, ESP, EIP, IF; #GP with no selector and SYSEXIT at ring 3).
; c686test.asm's frame. Run by pgrun.py --mp2 (against Bochs's
; p2_klamath).
        cpu p2
        org 0x7C00

STAGE2_LMA  equ 0x7E00
STAGE2_SECS equ 17
IDT_BASE    equ 0x6000
TSS_BASE    equ 0x6800
STACK0      equ 0x7000
STACK3      equ 0x5000
STACK0T     equ 0x6E00
PD          equ 0x10000
PT0         equ 0x11000
PT1         equ 0x12000
SEL_CODE    equ 0x08
SEL_DATA    equ 0x10
SEL_CODE3   equ 0x18 | 3
SEL_DATA3   equ 0x20 | 3
SEL_TSS     equ 0x28
RET_VEC     equ 0x30
TRAP_VEC    equ 0x32                ; a 32-bit trap gate: IF stays as it was
INTR_VEC    equ 0x33                ; a 32-bit interrupt gate: IF cleared
CR4_TSD     equ 0x04
CR4_PSE     equ 0x10
CR4_PGE     equ 0x80
CR4_PCE     equ 0x100

; ---------------------------------------------------------------- stage 1
        bits 16
stage1:
        cli
        cld
        xor ax, ax
        mov ds, ax
        mov es, ax
        mov ss, ax
        mov sp, 0x7C00
        mov ah, 0x02
        mov al, STAGE2_SECS
        mov ch, 0
        mov cl, 2
        mov dh, 0
        mov bx, STAGE2_LMA
        int 0x13
        jc  .h
        jmp stage2
.h:     hlt
        jmp .h
        times 510 - ($ - $$) db 0
        dw 0xAA55

; ---------------------------------------------------------------- stage 2
stage2:
        mov eax, cr0                ; ET as the machine came up
        mov [cr0_boot], eax
        mov al, 0xFF                ; every IRQ masked at the PIC: ring 3 runs with IF
        out 0x21, al                ; set, and a timer tick there reads as vector 8 (a
        out 0xA1, al                ; slow -V run on the host clock took one in T23)
        in al, 0x92                 ; A20 on
        or al, 2
        out 0x92, al
        lgdt [gdtr]
        mov eax, cr0
        or al, 1
        mov cr0, eax
        jmp SEL_CODE:pm32

        bits 32
pm32:
        mov ax, SEL_DATA
        mov ds, ax
        mov es, ax
        mov fs, ax
        mov gs, ax
        mov ss, ax
        mov esp, STACK0
        mov edi, IDT_BASE
        xor ecx, ecx
.idt:   mov eax, fault_stubs
        mov edx, ecx
        shl edx, 3
        add eax, edx
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        add edi, 8
        inc ecx
        cmp ecx, 32
        jb .idt
        mov edi, IDT_BASE + RET_VEC * 8
        mov eax, ret_trap
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0xEE00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + TRAP_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8F00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + INTR_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        lidt [idtr]
        mov dword [TSS_BASE + 4], STACK0T
        mov dword [TSS_BASE + 8], SEL_DATA
        mov word [TSS_BASE + 0x66], 0x68
        mov ax, SEL_TSS
        ltr ax
        mov dword [0x30000], 0x11223344
        mov dword [0x30004], 0x55667788
        mov dword [0x30020], 5
        mov dword [0x32000], 0x99AABBCC
        mov dword [0x34010], 0xDEADBEEF
        mov dword [0x36010], 0xFEEDFACE
        mov dword [0x30FFC], 0xAAAAAAAA     ; a CMPXCHG8B across into a read-only page
        mov dword [0x31000], 0xBBBBBBBB
        mov dword [0x400000], 0             ; (as a page table, with PSE off: nothing present)
        mov dword [0x400010], 0xCAFEBABE    ; in the 4 MB page at 400000
        mov dword [0x5FF000], 0x13579BDF
        mov edi, PD
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PD + 0], PT0 | 7
        mov dword [PD + 4], PT1 | 7
        mov edi, PT0
        mov eax, 7
        mov ecx, 1024
.pt0:   stosd
        add eax, 0x1000
        loop .pt0
        mov dword [PT0 + 0x32 * 4], 0x32000 | 5    ; user, read-only
        mov dword [PT0 + 0x31 * 4], 0x31000 | 5    ; user, read-only
        mov dword [PD + 8], 0x400000 | 0x87        ; linear 800000: a 4 MB page, user r/w (PS)
        mov dword [PD + 12], 0x400000 | 0x83       ; linear C00000: the same, supervisor
        mov edi, PT1
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PT1 + 0], 0x34000 | 7           ; linear 400000 -> 34000
        mov eax, PD
        mov cr3, eax
        mov eax, cr0
        or eax, 0x80000000
        mov cr0, eax
        jmp .paged
.paged:
        mov esi, msg_start
        call puts

        ; ---- CPUID: the signature, the features, leaf 2
        mov byte [tno], 1
        mov eax, 1
        cpuid
        call ok_eax
        mov byte [tno], 2
        mov eax, 1
        cpuid
        mov eax, edx
        call ok_eax
        mov byte [tno], 3
        mov eax, 2
        cpuid
        call ok_eax
        mov byte [tno], 4
        mov eax, 2
        cpuid
        mov eax, edx
        call ok_eax

        ; ---- MMX: each stub over each operand pair; Q<n> is mm0 after it
        mov dword [qno], 0
        mov esi, stubs
.op:    mov ebx, [esi]
        test ebx, ebx
        jz .shifts
        mov edi, pairs
        mov ecx, NPAIRS
.pair:  movq mm0, [edi]
        movq mm1, [edi + 8]
        call ebx
        call pr_mm0
        add edi, 16
        loop .pair
        add esi, 4
        jmp .op
.shifts:                                    ; by mm1 = each count, and by Ib
        mov esi, shstubs
.sop:   mov ebx, [esi]
        test ebx, ebx
        jz .imm
        mov edi, counts
        mov ecx, NCOUNTS
.cnt:   movq mm0, [pairs + 32]
        movq mm1, [edi]
        call ebx
        call pr_mm0
        add edi, 8
        loop .cnt
        add esi, 4
        jmp .sop
.imm:   mov esi, imstubs
.iop:   mov ebx, [esi]
        test ebx, ebx
        jz .hand
        movq mm0, [pairs + 32]
        call ebx
        call pr_mm0
        add esi, 4
        jmp .iop
.hand:
        ; ---- MOVD
        mov byte [tno], 0x60
        movq mm1, [pairs + 40]
        movd eax, mm1
        call ok_eax
        mov byte [tno], 0x61
        mov eax, 0x89ABCDEF
        movq mm0, [pairs + 16]
        movd mm0, eax                       ; zero-extended
        call pr_mm0
        mov byte [tno], 0x62
        movd mm0, [0x30000]
        call pr_mm0
        mov byte [tno], 0x63
        movd [tmp], mm1
        mov eax, [tmp]
        call ok_eax
        mov byte [tno], 0x64
        movq [tmpq], mm1
        mov eax, [tmpq + 4]
        call ok_eax

        ; ---- the x87's view: TOP and the tag word after MMX, after EMMS
        mov byte [tno], 0x70
        finit
        fld1
        fld1                                ; TOP 6, two tags valid
        movq mm2, [pairs + 32]
        fnstenv [env]
        mov eax, [env + 4]                  ; status word: TOP 0
        shl eax, 16
        mov ax, [env + 8]                   ; tag word: all valid
        call ok_eax
        mov byte [tno], 0x71
        emms
        fnstenv [env]
        mov eax, [env + 4]
        shl eax, 16
        mov ax, [env + 8]                   ; all empty
        call ok_eax
        mov byte [tno], 0x72                ; ST(0) after MMX wrote R0: exponent all ones
        finit
        movq mm0, [pairs + 32]
        fstp tword [tbuf]
        movzx eax, word [tbuf + 8]
        call ok_eax
        mov byte [tno], 0x73
        mov eax, [tbuf + 4]
        call ok_eax
        mov byte [tno], 0x74                ; an x87 load, read as MMX: the significand
        finit
        fld1
        movq [tmpq], mm7                    ; R7 = ST(0) (TOP 7)
        mov eax, [tmpq + 4]
        call ok_eax
        emms

        ; ---- exceptions: CR0.EM, CR0.TS, a pending x87 exception
        mov byte [tno], 0x80
        mov dword [resume], .t81
        mov eax, cr0
        or eax, 4                           ; EM
        mov cr0, eax
        paddb mm0, mm1                      ; #UD
        call ok_eax
.t81:   mov eax, cr0
        and eax, ~4
        mov cr0, eax
        mov byte [tno], 0x81
        mov dword [resume], .t82
        mov eax, cr0
        or eax, 8                           ; TS
        mov cr0, eax
        paddb mm0, mm1                      ; #NM
        call ok_eax
.t82:   clts
        mov byte [tno], 0x82
        mov dword [resume], .t83
        mov eax, cr0
        or eax, 0x20                        ; NE: #MF, not FERR#
        mov cr0, eax
        finit
        fldcw [cw_ze]
        fldz
        fld1
        fdiv st0, st1                       ; 1/0, ZE unmasked: pending
        paddb mm0, mm1                      ; #MF
        call ok_eax
.t83:   fnclex
        finit
        emms

        ; ---- SYSENTER / SYSEXIT
        mov byte [tno], 0x90
        mov dword [resume], .t91
        xor eax, eax
        xor edx, edx
        mov ecx, 0x174
        wrmsr                               ; no selector:
        sysenter                            ; #GP
        call ok_eax
.t91:   mov ecx, 0x174
        mov eax, SEL_CODE
        xor edx, edx
        wrmsr
        mov ecx, 0x175
        mov eax, 0x6C00
        wrmsr
        mov ecx, 0x176
        mov eax, sys_in
        wrmsr
        mov byte [tno], 0x91
        mov ecx, 0x174
        rdmsr
        call ok_eax
        mov byte [tno], 0x9A
        mov ebx, r3_sysexit                 ; SYSEXIT at ring 3: #GP
        call ring3
        mov [saved_esp], esp                ; the round trip, last: ring 3 by SYSEXIT, back by SYSENTER
        mov dword [resume], t60_done
        mov ax, SEL_DATA3
        mov ds, ax
        mov es, ax
        mov ecx, 0x5800                     ; ESP at ring 3
        mov edx, r3_sys                     ; EIP
        sti
        sysexit                             ; to ring 3 (r3_sys): CS 1B, SS 23; back by SYSENTER to sys_in
t60_done:
.t60:   xor eax, eax
        mov cr4, eax
        mov esi, msg_done
        call puts
        mov al, 0
        out 0xF4, al
.h:     hlt
        jmp .h
ring3:
        mov [saved_esp], esp
        mov dword [resume], .back
        mov ax, SEL_DATA3
        mov ds, ax
        mov es, ax
        push dword SEL_DATA3
        push dword STACK3
        push dword [r3flags]
        push dword SEL_CODE3
        push ebx
        iretd
.back:  ret

r3_rdpmc:       xor ecx, ecx
                rdpmc
                int RET_VEC
r3_sys:         mov eax, cs                 ; ring 3 after SYSEXIT
                mov ebx, ss
                mov edi, esp
                sysenter                    ; and back: sys_in at ring 0
sys_in:
        mov si, SEL_DATA
        mov ds, si
        mov es, si
        mov byte [tno], 0x92
        call ok_eax                         ; the ring-3 CS
        mov byte [tno], 0x93
        mov eax, ebx                        ; its SS
        call ok_eax
        mov byte [tno], 0x94
        mov eax, edi                        ; its ESP
        call ok_eax
        mov byte [tno], 0x96
        mov eax, cs
        call ok_eax
        mov byte [tno], 0x97
        mov eax, ss
        call ok_eax
        mov byte [tno], 0x98
        mov eax, esp
        call ok_eax
        mov byte [tno], 0x99
        pushfd
        pop eax
        and eax, 0x200                      ; IF cleared
        call ok_eax
        mov esp, [saved_esp]
        jmp t60_done
r3_sysexit:     sysexit
                int RET_VEC
pr_mm0:                                     ; "Q<n> " mm0, all registers kept
        pushad
        movq [tmpq], mm0
        mov esi, msg_q
        call puts
        mov eax, [qno]
        call hex16
        mov al, ' '
        out 0xE9, al
        mov eax, [tmpq + 4]
        call hex32
        mov eax, [tmpq]
        call hex32
        mov al, 10
        out 0xE9, al
        inc dword [qno]
        popad
        ret
