NPAIRS equ 8
NCOUNTS equ 10
        align 8
pairs:
        dq 0x0000000000000000, 0xFFFFFFFFFFFFFFFF
        dq 0x8000800080008000, 0x7FFF7FFF7FFF7FFF
        dq 0x80007FFF0001FFFF, 0x7F80FF0100FE8081
        dq 0x7F80FF0100FE8081, 0x8000800080008000
        dq 0xE1915F16C448E076, 0x110C8C003C4718AA
        dq 0x205FF2F9389C9F07, 0x38B2E08CAB2D3223
        dq 0xC467625A63FA7C5D, 0x708DFABF54756769
        dq 0x3EFFE777A4BC6D8B, 0xDE0C21E53ABFCD8A
